function check([n, k], actual, expected) {
  if (typeof actual !== 'string' || actual.length !== expected.length) return false;
  for (let i = 0; i < actual.length; i++) {
    const digit = actual.charCodeAt(i) - 48;
    if (digit < 0 || digit >= k) return false;
  }
  const windows = new Set();
  for (let i = 0; i + n <= actual.length; i++) windows.add(actual.slice(i, i + n));
  return windows.size === k ** n;
}

