function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 4) return 'n is between 1 and 4.';
  if (!Number.isInteger(k) || k < 1 || k > 10) return 'k is between 1 and 10.';
  if (k ** n > 4096) return 'k^n can be at most 4096.';
  return null;
}

