function crackSafe(n, k) {
  // Backtracking: extend the string one digit at a time, never repeating an n-digit window.
  const total = k ** n;
  const seen = new Set();
  const text = Array(n).fill('0');
  seen.add(text.join(''));
  const extend = () => {
    if (seen.size === total) return true;
    for (let d = k - 1; d >= 0; d--) {
      const window = text.slice(text.length - n + 1).join('') + d;
      if (seen.has(window)) continue;
      seen.add(window);
      text.push(String(d));
      if (extend()) return true;
      text.pop();
      seen.delete(window);
    }
    return false;
  };
  extend();
  return text.join('');
}

